def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Find the color forming the repeated horizontal and vertical grid lines.
    candidates = []
    for color in counts:
        if color == background:
            continue
        rr = [r for r in range(h) if sum(x == color for x in grid[r]) >= w * 0.65]
        cc = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= h * 0.65]
        if len(rr) >= 2 and len(cc) >= 2:
            candidates.append((len(rr) + len(cc), color, rr, cc))
    if candidates:
        _, divider, rr, cc = max(candidates)
    else:
        # Fallback for patterns where lines are sparse or interrupted.
        divider = min(counts, key=lambda x: counts[x])
        rr = [r for r in range(h) if sum(x == divider for x in grid[r]) >= w * 0.65]
        cc = [c for c in range(w) if sum(grid[r][c] == divider for r in range(h)) >= h * 0.65]

    def collapse(indices):
        groups = []
        for x in indices:
            if not groups or x > groups[-1][-1] + 1:
                groups.append([x])
            else:
                groups[-1].append(x)
        return [g[0] for g in groups]

    rr, cc = collapse(rr), collapse(cc)
    if len(rr) < 2 or len(cc) < 2:
        return [[background]]

    out = []
    for r in rr[:-1]:
        row = []
        for c in cc[:-1]:
            v = grid[r][c]
            row.append(background if v == divider else v)
        out.append(row)
    return out
